# -*- coding: utf-8 -*-
# Сверка с ответами учебника Алимов 9, часть 3 (расхождения 135–193): пересчитано вручную + SymPy (check_al3.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Алимов 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Алимов 9 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
P["G9_TB_ПовтКурс_521_4"] = {"q": r"Решите методом интервалов неравенство: $(2-x)(x+3x^{2})\geq 0$", "k": r"$x \le -\dfrac{1}{3}$, $0 \le x \le 2$", "src": SRC,
  "why": "опечатка учебника в условии (Алимов 9, № 521 (4)): напечатано (x + 3x)², при котором ответ был бы просто x ≤ 2 и варианты «x ≤ 2», «x ≤ 2, x = −3» совпадали бы с ключом; ответ учебника x ≤ −1/3, 0 ≤ x ≤ 2 соответствует (2 − x)(x + 3x²) ≥ 0 — условие и ключ восстановлены по нему"}
K("G9_TB_УКГ2_197_4", r"$(6; 2)$, $(2; 6)$", "второе уравнение: (x − y)² = 16 ⇒ x − y = ±4 при x + y = 8 (было «любая пара с суммой 8»)")
K("G9_TB_УКГ2_200_4", r"$(-1; 4)$, $(2{,}4; 0{,}6)$", "4(y − x) = −5xy, y = 3 − x ⇒ 5x² − 7x − 12 = 0 ⇒ x = −1 или 2,4 (было (4; −1): 1/4 + 1 ≠ −5/4)")
K("G9_TB_2_4_2", r"$0$", "x² + x = 0 ⇒ x = 0 или −1; из чисел −2; 0; 1; √3 нулём является только 0 (в ключе было −1, которого нет в списке)")
K("G9_TB_2_4_3", r"$\sqrt{3}$", "x² − 3 = 0 ⇒ x = ±√3; из чисел −2; 0; 1; √3 нулём является только √3 (в ключе было −√3, которого нет в списке)")
K("G9_TB_13_155_1", r"$(-2; 1)$, $(0{,}25; 7{,}75)$", "y = 3x + 7 ⇒ 4x² + 7x − 2 = 0 ⇒ x = −2 или 1/4 (было (−0,5; 5,5): 0,25 − 2,75 ≠ 2)")
K("G9_TB_15_173_2", r"$x=5$, $y=1$", "xy²(1 + y) = 10 и x(1 + y) = 10 ⇒ y² = 1; y = −1 невозможно ⇒ (5; 1) (в ключе были не решения (80; −1/2) и (5; −2))")
K("G9_TB_ПовтКурс_523", r"средняя линия $> 6{,}2$ см, высота $> 3{,}1$ см", "S = m·h = 2h² > 19,22 ⇒ h > 3,1, m > 6,2 (было √4,805 ≈ 2,19 — площадь поделена лишний раз)")
K("G9_TB_УКГ2_194_2", r"$(4; 1)$, $(-1; -4)$", "x = y + 3 ⇒ y² + 3y − 4 = 0 ⇒ y = 1 или −4 (было (1; −2): 1 + 6 ≠ 13)", dadd=OLD(r"$(4; 1), (1; -2)$", "(1; −2) не решение"))
K("G9_TB_13_163_1", r"$(4;2)$, $(2;4)$", "x − y = ±2, x + y = 6 (было (8; −2): (x − y)² = 100)", dadd=OLD(r"$(4;2), (8;-2)$", "(8; −2) не решение"))
